actions.script:
const given = name => (typeof ec.context[name] === 'undefined' || ec.context[name] === '' ? null : ec.context[name])
const services = {preview: 'preview#CheckIn', checkIn: 'checkIn#Registration', resolve: 'resolve#EntryCode'}
let out = {}
let error = ''
ec.message.pushErrors()
try {
    out = ec.service.sync().name('mantle.work.EventRegistrationServices.' + services[given('op')])
        .parameters({registrationPolicyId: given('askOffer') || given('registrationPolicyId'), entryCode: given('entryCode'),
            scanText: given('entryCode'), term: given('term'), registrationId: given('registrationId'),
            reason: given('reason'), override: given('override'), operationKey: given('operationKey')})
        .disableAuthz().requireNewTransaction(true).call() || {}
    if (ec.message.hasError()) error = ec.message.getErrorsString()
} catch (e) {
    error = String(e.message || e)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
ec.web.sendJsonResponse({out, error, userId: ec.user.userId || null})
